CREATE VIEW active_customers AS
SELECT id, name, email
FROM customers
WHERE deleted_at IS NULL AND status = 'active';

SELECT name FROM active_customers WHERE email LIKE '%@example.com';

CREATE PROCEDURE dbo.TransferFunds @FromId int, @ToId int, @Amount int AS
BEGIN
  SET XACT_ABORT ON;               -- any error rolls the whole transaction back
  IF @Amount <= 0 RETURN 1;
  BEGIN TRAN;
    UPDATE accounts SET balance = balance - @Amount
    WHERE id = @FromId AND balance >= @Amount;
    IF @@ROWCOUNT = 0 BEGIN ROLLBACK; RETURN 4; END
    UPDATE accounts SET balance = balance + @Amount WHERE id = @ToId;
  COMMIT;
  RETURN 0;
END;

EXEC dbo.TransferFunds @FromId = 1, @ToId = 2, @Amount = 30;
